120: static int call_cpuidle(struct cpuidle_driver *drv, struct cpuidle_device *dev,
121: 		      int next_state)
122: {
123: 	/*
124: 	 * The idle task must be scheduled, it is pointless to go to idle, just
125: 	 * update no idle residency and return.
126: 	 */
127: 	if (current_clr_polling_and_test()) {
128: 		dev->last_residency_ns = 0;
129: 		local_irq_enable();
130: 		return -EBUSY;
131: 	}
132: 
133: 	/*
134: 	 * Enter the idle state previously returned by the governor decision.
135: 	 * This function will block until an interrupt occurs and will take
136: 	 * care of re-enabling the local interrupts
137: 	 */
138: 	return cpuidle_enter(drv, dev, next_state);
139: }
