141: /**
142:  * cpuidle_idle_call - the main idle function
143:  *
144:  * NOTE: no locks or semaphores should be used here
145:  *
146:  * On architectures that support TIF_POLLING_NRFLAG, is called with polling
147:  * set, and it returns with polling set.  If it ever stops polling, it
148:  * must clear the polling bit.
149:  */
150: static void cpuidle_idle_call(void)
151: {
152: 	struct cpuidle_device *dev = cpuidle_get_device();
153: 	struct cpuidle_driver *drv = cpuidle_get_cpu_driver(dev);
154: 	int next_state, entered_state;
155: 
156: 	/*
157: 	 * Check if the idle task must be rescheduled. If it is the
158: 	 * case, exit the function after re-enabling the local irq.
159: 	 */
160: 	if (need_resched()) {
161: 		local_irq_enable();
162: 		return;
163: 	}
164: 
165: 	/*
166: 	 * The RCU framework needs to be told that we are entering an idle
167: 	 * section, so no more rcu read side critical sections and one more
168: 	 * step to the grace period
169: 	 */
170: 
171: 	if (cpuidle_not_available(drv, dev)) {
172: 		tick_nohz_idle_stop_tick();
