174: 		default_idle_call();
175: 		goto exit_idle;
176: 	}
177: 
178: 	/*
179: 	 * Suspend-to-idle ("s2idle") is a system state in which all user space
180: 	 * has been frozen, all I/O devices have been suspended and the only
181: 	 * activity happens here and in interrupts (if any). In that case bypass
182: 	 * the cpuidle governor and go straight for the deepest idle state
183: 	 * available.  Possibly also suspend the local tick and the entire
184: 	 * timekeeping to prevent timer interrupts from kicking us out of idle
185: 	 * until a proper wakeup interrupt happens.
186: 	 */
