3627: /*
3628:  * Update the idle state of a CPU to @idle.
3629:  *
3630:  * If @do_notify is true, ops.update_idle() is invoked to notify the scx
3631:  * scheduler of an actual idle state transition (idle to busy or vice
3632:  * versa). If @do_notify is false, only the idle state in the idle masks is
3633:  * refreshed without invoking ops.update_idle().
3634:  *
3635:  * This distinction is necessary, because an idle CPU can be "reserved" and
3636:  * awakened via scx_bpf_pick_idle_cpu() + scx_bpf_kick_cpu(), marking it as
3637:  * busy even if no tasks are dispatched. In this case, the CPU may return
3638:  * to idle without a true state transition. Refreshing the idle masks
3639:  * without invoking ops.update_idle() ensures accurate idle state tracking
3640:  * while avoiding unnecessary updates and maintaining balanced state
3641:  * transitions.
3642:  */
3643: void __scx_update_idle(struct rq *rq, bool idle, bool do_notify)
3644: {
3645: 	int cpu = cpu_of(rq);
3646: 
3647: 	lockdep_assert_rq_held(rq);
3648: 
3649: 	/*
3650: 	 * Trigger ops.update_idle() only when transitioning from a task to
3651: 	 * the idle thread and vice versa.
3652: 	 *
3653: 	 * Idle transitions are indicated by do_notify being set to true,
3654: 	 * managed by put_prev_task_idle()/set_next_task_idle().
3655: 	 */
3656: 	if (SCX_HAS_OP(update_idle) && do_notify && !scx_rq_bypassing(rq))
3657: 		SCX_CALL_OP(SCX_KF_REST, update_idle, cpu_of(rq), idle);
3658: 
3659: 	/*
3660: 	 * Update the idle masks:
3661: 	 * - for real idle transitions (do_notify == true)
3662: 	 * - for idle-to-idle transitions (indicated by the previous task
3663: 	 *   being the idle thread, managed by pick_task_idle())
3664: 	 *
3665: 	 * Skip updating idle masks if the previous task is not the idle
3666: 	 * thread, since set_next_task_idle() has already handled it when
3667: 	 * transitioning from a task to the idle thread (calling this
3668: 	 * function with do_notify == true).
3669: 	 *
3670: 	 * In this way we can avoid updating the idle masks twice,
3671: 	 * unnecessarily.
3672: 	 */
3673: 	if (static_branch_likely(&scx_builtin_idle_enabled))
3674: 		if (do_notify || is_idle_task(rq->curr))
3675: 			update_builtin_idle(cpu, idle);
3676: }
